INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12501, 'Job 27:8', 'Job', 27, 8, '&nbsp;ځکه چې د خُدائ نه د منکرو خلقو اُميد به څۀ وى چې کله هغوئ د ژوند نه لاس ووينځى، کله چې خُدائ پاک د هغوئ نه ژوند واخلى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12502, 'Job 27:9', 'Job', 27, 9, '&nbsp;چې کله مصيبت په هغوئ باندې راشى نو خُدائ پاک به د هغوئ ژړا اورى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12503, 'Job 27:10', 'Job', 27, 10, '&nbsp;هغوئ به د قادر خُدائ سره خوشحاله شى څۀ؟ هغوئ به هر وخت خُدائ پاک ته آواز کولے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12504, 'Job 27:11', 'Job', 27, 11, '&nbsp;زۀ به تا ته د خُدائ پاک د طاقت په حقله ښودنه وکړم، څۀ چې د قادر خُدائ سره وى نو زۀ به هغه نۀ پټوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12505, 'Job 27:12', 'Job', 27, 12, '&nbsp;تاسو دا هر څۀ په خپله ليدلى دى، خو بيا هم تاسو ما ته دا فضول خبرې کوئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12506, 'Job 27:13', 'Job', 27, 13, '&nbsp;”دا د خُدائ پاک سره د بدعمله کسانو برخه ده، او دا هغه ميراث دے چې ظالمانو ته د قادر خُدائ د طرف نه ملاويږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12507, 'Job 27:14', 'Job', 27, 14, '&nbsp;کۀ د هغوئ اولاد ډېر هم وى، خو د هغوئ بچى به په جنګ کښې او د لوږې نه مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12508, 'Job 27:15', 'Job', 27, 15, '&nbsp;څوک چې پاتې وى نو هغوئ به په وبا مړۀ شى، او د هغوئ کونډې به هم په هغوئ باندې ژړا ونۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12509, 'Job 27:16', 'Job', 27, 16, '&nbsp;هغوئ سره سپين زر د خاورو نه زيات دى، او بې‌حسابه جامې ورسره دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12510, 'Job 27:17', 'Job', 27, 17, '&nbsp;هغوئ به دا رايوځائ کړى، خو نېکان به دا واغوندى، او بې‌ګناه کسان به سپين زر په خپلو کښې تقسيم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12511, 'Job 27:18', 'Job', 27, 18, '&nbsp;بدعمله کسان خپل کورونه د جالو په شان داسې کمزورى جوړوى، لکه چې څوکيداران څپر جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12512, 'Job 27:19', 'Job', 27, 19, '&nbsp;هغوئ به د دولت سره څملى، خو چې سترګې وغړوى، نو مال به يې ختم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12513, 'Job 27:20', 'Job', 27, 20, '&nbsp;يره د سېلاب په شان په هغوئ باندې غالبه شى، او د شپې طوفان يې يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12514, 'Job 27:21', 'Job', 27, 21, '&nbsp;د نمرخاتۀ طرف هوا هغوئ اوچت کړى او هغوئ ختم شى، او دا هوا يې په مخه يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12515, 'Job 27:22', 'Job', 27, 22, '&nbsp;دا په بې‌رحمۍ سره په هغوئ باندې راوغورزيږى، اګر چې هغوئ د تښتېدو پوره کوشش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12516, 'Job 27:23', 'Job', 27, 23, '&nbsp;هوا په هغوئ پسې داسې شور جوړوى لکه چې سړے په چا پورې خندا کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12517, 'Job 28:1', 'Job', 28, 1, '&nbsp;”بې‌شکه چې د سپينو زرو يو کان وى، او د سرو زرو د صفا کولو دپاره يو ځائ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12518, 'Job 28:2', 'Job', 28, 2, '&nbsp;اوسپنه د زمکې نه راويستلے شى، او د کاڼو نه ويلې شوې تانبه راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12519, 'Job 28:3', 'Job', 28, 3, '&nbsp;انسان په تيارۀ کښې رڼا ځلوى، او د دُنيا آخرى حد معلوموى، او د زمکې لاندې په تيارۀ کښې قيمتى کاڼى لټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12520, 'Job 28:4', 'Job', 28, 4, '&nbsp;هغوئ د انسان د اوسېدو نه لرې په زمکه کښې سورنګونه جوړوى، هغوئ په کان کښې په پړو باندې کوزيږى او خېژى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12521, 'Job 28:5', 'Job', 28, 5, '&nbsp;په دې زمکه پاس خوراک لوئيږى خو دا زمکه لاندې داسې ده لکه د اور.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12522, 'Job 28:6', 'Job', 28, 6, '&nbsp;د دې زمکې په کاڼو کښې نيلم شته، او د دې په خاوره کښې سرۀ زر پراتۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12523, 'Job 28:7', 'Job', 28, 7, '&nbsp;د هغه خزانې لار يو ښکارى مارغۀ ته هم نۀ ده معلومه، او نۀ باز هغه ليدلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12524, 'Job 28:8', 'Job', 28, 8, '&nbsp;ځنګلى ځناورو په هغې باندې قدم نۀ دے اېښے، او زمرے په هغې باندې تېر شوے نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12525, 'Job 28:9', 'Job', 28, 9, '&nbsp;بنى آدم په سختو کاڼو کښې کار کوى، او د غرونو بېخونه اړَوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12526, 'Job 28:10', 'Job', 28, 10, '&nbsp;هغوئ په کاڼو کښې سورنګونه جوړوى، او هغوئ قيمتى کاڼى پېدا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12527, 'Job 28:11', 'Job', 28, 11, '&nbsp;هغوئ د دريابونو بېخونه لټوى، او هغوئ پټ څيزونه رڼا ته راوباسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12528, 'Job 28:12', 'Job', 28, 12, '&nbsp;خو هغوئ ته پته نشته چې حِکمت به چرته ملاويږى؟ او د پوهې ځائ چرته دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12529, 'Job 28:13', 'Job', 28, 13, '&nbsp;بنى آدم د دې د قيمت نه خبر نۀ دے، او دا په دې دُنيا کښې نۀ ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12530, 'Job 28:14', 'Job', 28, 14, '&nbsp;سمندر وائى چې دا په ما کښې نشته، او درياب وائى چې دا په ما کښې نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12531, 'Job 28:15', 'Job', 28, 15, '&nbsp;نۀ دا په سپينو زرو اخستلے شى، او نۀ دا په سرو زرو اخستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12532, 'Job 28:16', 'Job', 28, 16, '&nbsp;د اوفير سرۀ زر د دې قيمت نۀ شى پوره کولے، نۀ يې اونيکس کاڼى او نۀ يې نيلم کاڼى پوره کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12533, 'Job 28:17', 'Job', 28, 17, '&nbsp;سرۀ زر او قيمتى کاڼى د حِکمت برابر نۀ شى کېدے، او نۀ دا د سوچه سرو زرو په کالو باندې بدلولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12534, 'Job 28:18', 'Job', 28, 18, '&nbsp;مرجان او بلور غمى هيڅ هم نۀ دى، د حِکمت قيمت د ملغلرو نه اوچت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12535, 'Job 28:19', 'Job', 28, 19, '&nbsp;د ايتهوپيا طوپاز د دې برابر نۀ دے، او نۀ سوچه سرۀ زر د دې قيمت پوره کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12536, 'Job 28:20', 'Job', 28, 20, '&nbsp;نو بيا حِکمت د کوم ځائ نه راځى؟ او د پوهې مقام چرته دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12537, 'Job 28:21', 'Job', 28, 21, '&nbsp;دا د ټول مخلوق د سترګو نه پناه دے، او د هوا د مارغانو نه پټ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12538, 'Job 28:22', 'Job', 28, 22, '&nbsp;په عالمِ ارواح کښې صرف د دې افواه اورېدلے شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12539, 'Job 28:23', 'Job', 28, 23, '&nbsp;صرف خُدائ پاک د حِکمت په طريقه پوهه دے، او هغۀ ته د دې د مقام پته ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12540, 'Job 28:24', 'Job', 28, 24, '&nbsp;ځکه چې هغه ټولې دُنيا ته ګورى، او هغه د آسمانونو لاندې هر يو څيز وينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12541, 'Job 28:25', 'Job', 28, 25, '&nbsp;کله چې هغۀ هوا ته طاقت ورکړو، او په وريځو کښې يې باران کېښودو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12542, 'Job 28:26', 'Job', 28, 26, '&nbsp;کله چې هغۀ د باران دپاره اصُول مقرر کړل، او د تندر دپاره يې يوه لاره مقرره کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12543, 'Job 28:27', 'Job', 28, 27, '&nbsp;بيا هغۀ حِکمت وليدو او د دې اندازه يې واخستله، هغۀ دا تيار کړو او ښۀ يې وکتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12544, 'Job 28:28', 'Job', 28, 28, '&nbsp;او هغۀ بنيادمو ته وفرمائيل، چې د مالِک خُدائ نه يره کښې حِکمت دے، او بدعملى پرېښودل عقلمندى ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12545, 'Job 29:1', 'Job', 29, 1, '&nbsp;ايُوب خپله خبره بيا شروع کړه او وې فرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12546, 'Job 29:2', 'Job', 29, 2, '&nbsp;”کاش چې تېر عُمر زما بيا راغلے وے، چې په کوم وخت کښې د خُدائ پاک په ما باندې نظر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12547, 'Job 29:3', 'Job', 29, 3, '&nbsp;هغۀ ما ته رڼا کړه کله چې زۀ په تيارۀ کښې ګرځېدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12548, 'Job 29:4', 'Job', 29, 4, '&nbsp;کله چې زۀ په ځوانۍ کښې وم، او د خُدائ پاک د دوستۍ نظر زما په کور باندې وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12549, 'Job 29:5', 'Job', 29, 5, '&nbsp;کله چې قادر خُدائ زما مل وو، او زما بچى زما نه ګېرچاپېره تاو وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12550, 'Job 29:6', 'Job', 29, 6, '&nbsp;کله چې ما کره پئ ډېر تېر وُو، او ما کره تېل د نِهرونو په شان بهېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12551, 'Job 29:7', 'Job', 29, 7, '&nbsp;کله چې زۀ د ښار دروازې ته تلم، او د جرګې په ځائ کښې به د عزتمندو مشرانو سره کښېناستم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12552, 'Job 29:8', 'Job', 29, 8, '&nbsp;نو ځوانان به پاڅېدل او لا به ړل، او بوډاګان به اوچت شول او وبه درېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12553, 'Job 29:9', 'Job', 29, 9, '&nbsp;مشران خلق به چپ شول، او په خپلو خُلو به يې لاسونه کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12554, 'Job 29:10', 'Job', 29, 10, '&nbsp;د خانانو آوازونه به غلى شول، او د هغوئ د خولې نه به يوه خبره هم نۀ وتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12555, 'Job 29:11', 'Job', 29, 11, '&nbsp;هر چا به چې زما په حقله اورېدل نو هغوئ به زما صِفت کولو. چې هر چا به زۀ ليدلم نو هغوئ به زما ښۀ وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12556, 'Job 29:12', 'Job', 29, 12, '&nbsp;کله به چې غريبانانو څۀ غوښتل نو ما به يې مدد کولو، او د حاجتمندو يتيمانانو مرسته به مې کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12557, 'Job 29:13', 'Job', 29, 13, '&nbsp;چې څوک به سخت غمژن وُو نو هغوئ به زما ښۀ وئيل، او زما په وجه به کونډو د خوشحالۍ سندرې وئيلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12558, 'Job 29:14', 'Job', 29, 14, '&nbsp;ما د صداقت هر يو کار کولو، اِنصاف او صداقت د يوې چُوغې او د پټکى په شان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12559, 'Job 29:15', 'Job', 29, 15, '&nbsp;زۀ د ړندو دپاره سترګې وم، او د ګوډيانو دپاره پښې وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12560, 'Job 29:16', 'Job', 29, 16, '&nbsp;زۀ د ضرورتمندو د پلار په شان وم، او د مسافرو مرسته به مې کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12561, 'Job 29:17', 'Job', 29, 17, '&nbsp;ما د ظالمانو ژامنې ماتې کړې، او د هغوئ نه مې مظلومان خلاص کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12562, 'Job 29:18', 'Job', 29, 18, '&nbsp;زما خيال دا وو چې ډېر عُمر به ژوندے يم او په آرام سره به په کور کښې مړ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12563, 'Job 29:19', 'Job', 29, 19, '&nbsp;زۀ د داسې ونې په شان وم چې جرړې يې اوبو ته رسېدلې وى او څانګې يې ټوله شپه په پرخه لامدې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12564, 'Job 29:20', 'Job', 29, 20, '&nbsp;خلقو به هر وخت زما صِفت کولو او زما په مټو به لا هم زور زياتېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12565, 'Job 29:21', 'Job', 29, 21, '&nbsp;هر چا به زما نصيحت اورېدو، او په خاموشۍ سره به زما د خبرې په انتظار کښې ناست وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12566, 'Job 29:22', 'Job', 29, 22, '&nbsp;کله چې ما خبرې وکړې نو هغوئ بيا څۀ ونۀ وئيل، او زما خبرې په هغوئ لکه د شاتو لګېدې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12567, 'Job 29:23', 'Job', 29, 23, '&nbsp;هغوئ زما د خبرو داسې اِنتظار کولو لکه چې د باران اِنتظار کوى، په هغوئ باندې زما خبرې د سپرلى د باران په شان لګېدې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12568, 'Job 29:24', 'Job', 29, 24, '&nbsp;کله چې هغوئ بې‌حوصلې وُو نو ما د هغوئ ډاډګيرنه کوله، او زما په وجه د هغوئ حوصله مضبوطه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12569, 'Job 29:25', 'Job', 29, 25, '&nbsp;ما د مشر په شان هغوئ ته وښودل چې څۀ به کوى، زۀ د لښکر د بادشاه په شان د هغوئ سره اوسېدم، او غمژنو له مې تسلى ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12570, 'Job 30:1', 'Job', 30, 1, '&nbsp;اوس زما نه کشران هم په ما پورې خندا کوى، او دا هغه کشران دى چې د چا پلاران هم زما د رَمو د سپو برابر نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12571, 'Job 30:2', 'Job', 30, 2, '&nbsp;د هغوئ طاقت به ما له څۀ فائده راکړى؟ د هغوئ ټول زور ختم شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12572, 'Job 30:3', 'Job', 30, 3, '&nbsp;هغوئ دومره غريبانان او اوږى وُو چې د شپې به يې په صحرا کښې د بوټو جرړې خوړلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12573, 'Job 30:4', 'Job', 30, 4, '&nbsp;هغوئ د صحرا نه بوټى راويستى دى او خوړلى يې دى، د هغوئ خوراک د جاړو بوټو جرړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12574, 'Job 30:5', 'Job', 30, 5, '&nbsp;هغوئ د معاشرې نه شړلے شوى دى، او خلق په هغوئ پسې داسې چغې وهى لکه چې دوئ غلۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12575, 'Job 30:6', 'Job', 30, 6, '&nbsp;هغوئ د اوچو شوو دريابونو په مېدانونو کښې ژوند تېروى، او د زمکې په غارونو او ګټو کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12576, 'Job 30:7', 'Job', 30, 7, '&nbsp;هغوئ د غنو بوټو لاندې غوريږى، او د جاړو بوټو لاندې به راغونډيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12577, 'Job 30:8', 'Job', 30, 8, '&nbsp;هغوئ بې‌غېرته او بې‌اصله دى، او د مُلک نه شړلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12578, 'Job 30:9', 'Job', 30, 9, '&nbsp;او اوس هغوئ په ما پورې په سندرو کښې خندا کوى، زۀ د هغوئ په سندرو کښې سپک يادېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12579, 'Job 30:10', 'Job', 30, 10, '&nbsp;هغوئ زما نه نفرت کوى او هغوئ ما سره هيڅ تعلق نۀ لرى، او ښۀ په زړۀ ورتيا زما په مخ توکاڼى تُوکى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12580, 'Job 30:11', 'Job', 30, 11, '&nbsp;ځکه چې خُدائ پاک زۀ کمزورے او عاجز کړے يم، نو ځکه هغوئ زما ادب نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12581, 'Job 30:12', 'Job', 30, 12, '&nbsp;زما په مخکښې خلق راپاڅى او ومې غورزوى او زما په لار کښې دامونه اچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12582, 'Job 30:13', 'Job', 30, 13, '&nbsp;هغوئ زما لار بندوى، او هغوئ زما د تباه کولو دپاره هر څۀ کوى، هغوئ ته پته ده چې زما د تپوس کولو والا څوک نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12583, 'Job 30:14', 'Job', 30, 14, '&nbsp;هغوئ په ما باندې د هر طرف نه راشى، کله چې زۀ لاندې يم نو هغوئ په ما باندې راټوپ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12584, 'Job 30:15', 'Job', 30, 15, '&nbsp;اوس زۀ په يره کښې اوسېږم، او زما عزت هوا اوړے دے، او زما مال دولت د وريځو په شان فنا شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12585, 'Job 30:16', 'Job', 30, 16, '&nbsp;او اوس زما روح زما نه وتلے دے، او د مصيبت په وخت کښې راګېر يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12586, 'Job 30:17', 'Job', 30, 17, '&nbsp;شپه زما د هډُوکو دپاره د دردونو سبب ګرځى، او چې کوم درد ما خورى په هغې کښې هيڅ کمے نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12587, 'Job 30:18', 'Job', 30, 18, '&nbsp;خپل زورَور لاس سره خُدائ پاک زما جامې نيولې دى، هغۀ زۀ زما د چُوغې د غاړې نه نيولے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12588, 'Job 30:19', 'Job', 30, 19, '&nbsp;هغۀ زۀ خټو ته غورزولے يم، او زۀ د خاورو او ايرو په شان شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12589, 'Job 30:20', 'Job', 30, 20, '&nbsp;زۀ تا ته فرياد کوم او تۀ زما فرياد نۀ اورې، زۀ ستا په وړاندې ودرېږم خو تۀ ما ته ګورې قدرې هم نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12590, 'Job 30:21', 'Job', 30, 21, '&nbsp;تا ما سره زياتے شروع کړے دے، او د خپل طاقت سره ما له تکليف راکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12591, 'Job 30:22', 'Job', 30, 22, '&nbsp;تا زۀ په هوا باندې اوچت کړے يم، او په طوفان کښې دې تباه کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12592, 'Job 30:23', 'Job', 30, 23, '&nbsp;ما ته پته ده چې تۀ به ما مرګ له بوځې، هغه کور ته کوم چې د ټولو ژوندو دپاره تيار شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12593, 'Job 30:24', 'Job', 30, 24, '&nbsp;څوک د ضرورتمندو خِلاف کار نۀ کوى، کله چې په يو مصيبت کښې هغوئ د مدد دپاره چغې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12594, 'Job 30:25', 'Job', 30, 25, '&nbsp;څوک چې په تکليف کښې وُو ولې ما د هغوئ دپاره ژړا ونۀ کړه څۀ؟ او زما زړۀ په غريبانانو باندې خفه نۀ وو څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12595, 'Job 30:26', 'Job', 30, 26, '&nbsp;خو کله چې ما د ښۀ‌والى لټون وکړو، نو بدوالے راغلو، او کله چې ما د رڼا اِنتظار وکړو، نو تيارۀ راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12596, 'Job 30:27', 'Job', 30, 27, '&nbsp;زما زړۀ بې‌قراره او په تکليف دے، او سخت وخت په ما باندې راغلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12597, 'Job 30:28', 'Job', 30, 28, '&nbsp;زۀ په داسې تيارۀ کښې ګرځم چې رڼا نۀ وى، زۀ د خلقو په مخکښې ودرېږم او د مدد دپاره چغې وهم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12598, 'Job 30:29', 'Job', 30, 29, '&nbsp;زۀ د ګيدړانو ورور يم، او د ګونګا ملګرے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12599, 'Job 30:30', 'Job', 30, 30, '&nbsp;زما څرمن توره شى او وغورزيږى، او زما بدن د تبې په وجه سور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12600, 'Job 30:31', 'Job', 30, 31, '&nbsp;زما د رباب ساز په ژړا بدل شوے دے، او زما د شپېلۍ آواز د ژړا نه ډک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');